        { t: c.rent ? money0(c.rent) : "no rent set", color: c.rent ? PALETTE.slate : PALETTE.faint },
        { t: c.lettable && c.rent && d != null ? money0(c.rent * 12 / 365 * d) : "-", color: c.lettable && c.rent && d != null ? AMBER : PALETTE.faint }
