    font(6.8, "bold", PILL[c.status] || PALETTE.muted);
    text(fit(c.letLabel, COLS.status - 2), x + 2, ty);
    x += COLS.status;
    font(6.8, "normal", PALETTE.slate);
    text(c.rent ? money0(c.rent) : "-", x + COLS.rent - 2, ty, { align: "right" });
