    text("Owes rent", kx + 5.5, y);
    kx += 5.5 + width("Owes rent") + 4;
    doc.setFillColor(...mix(AMBER, WHITE, 0.12));
    doc.rect(kx, y - 2.6, 4, 3.4, "F");
    text("Not let", kx + 5.5, y);
